// KeyboardCatalog is the checked-in keyboard command catalog the browser
// and the server share (client/shared/data/keymap.json): each command's id,
// scope and default binding. Regenerate it when the catalog changes.
type KeyboardCatalog struct{}

// Text answers the catalog commands as JSON.
func (KeyboardCatalog) Text() string {
	return `[{"id":"core:compose","scope":"global","binding":"c"},{"id":"core:search","scope":"mailbox","binding":"/"},{"id":"core:refresh","scope":"mailbox","binding":"shift+r"},{"id":"core:toggle-screenshot-mode","scope":"global","binding":"mod+shift+p"},{"id":"core:show-shortcuts","scope":"global","binding":"?"},{"id":"core:go-inbox","scope":"global","binding":"g i"},{"id":"core:go-drafts","scope":"global","binding":"g d"},{"id":"core:go-sent","scope":"global","binding":"g s"},{"id":"core:go-archive","scope":"global","binding":"g a"},{"id":"core:go-spam","scope":"global","binding":"g x"},{"id":"core:go-trash","scope":"global","binding":"g t"},{"id":"core:go-settings","scope":"global","binding":"g ,"},{"id":"core:select-all","scope":"mailbox","binding":"* a"},{"id":"core:deselect-all","scope":"mailbox","binding":"esc"},{"id":"navigation:next-email","scope":"mailbox","binding":"j"},{"id":"navigation:prev-email","scope":"mailbox","binding":"k"},{"id":"navigation:scroll-down","scope":"mailbox","binding":"d"},{"id":"navigation:scroll-up","scope":"mailbox","binding":"u"},{"id":"email:open","scope":"mailbox","binding":"enter"},{"id":"email:star","scope":"mail","binding":"s"},{"id":"email:archive","scope":"mail","binding":"e"},{"id":"email:trash","scope":"mail","binding":"#"},{"id":"email:report-spam","scope":"mail","binding":"!"},{"id":"email:mark-read","scope":"mail","binding":"shift+i"},{"id":"email:mark-unread","scope":"mail","binding":"shift+u"},{"id":"email:reply","scope":"reader","binding":"r"},{"id":"email:reply-all","scope":"reader","binding":"shift+r"},{"id":"email:forward","scope":"reader","binding":"f"},{"id":"core:print-thread","scope":"reader","binding":"mod+p"},{"id":"core:find-in-thread","scope":"reader","binding":"mod+f"},{"id":"core:find-in-thread-next","scope":"reader-find","binding":"mod+g"},{"id":"core:find-in-thread-previous","scope":"reader-find","binding":"mod+shift+g"},{"id":"github:open","scope":"reader-no-find","binding":"mod+g"},{"id":"composer:send","scope":"composer","binding":"mod+enter"},{"id":"composer:discard","scope":"composer","binding":"esc"},{"id":"calendar:move-event-up","scope":"calendar","binding":"up"},{"id":"calendar:move-event-down","scope":"calendar","binding":"down"},{"id":"calendar:move-event-left","scope":"calendar","binding":"left"},{"id":"calendar:move-event-right","scope":"calendar","binding":"right"},{"id":"calendar:resize-event-up","scope":"calendar","binding":"shift+up"},{"id":"calendar:resize-event-down","scope":"calendar","binding":"shift+down"},{"id":"calendar:resize-event-left","scope":"calendar","binding":"shift+left"},{"id":"calendar:resize-event-right","scope":"calendar","binding":"shift+right"},{"id":"calendar:view-day","scope":"calendar","binding":"mod+1"},{"id":"calendar:view-week","scope":"calendar","binding":"mod+2"},{"id":"calendar:view-month","scope":"calendar","binding":"mod+3"},{"id":"calendar:view-agenda","scope":"calendar","binding":"mod+4"},{"id":"calendar:go-to-today","scope":"calendar","binding":"mod+t"},{"id":"calendar:navigate-next","scope":"calendar","binding":"mod+right"},{"id":"calendar:navigate-previous","scope":"calendar","binding":"mod+left"},{"id":"calendar:refresh-calendars","scope":"calendar","binding":"mod+shift+r"}]`
}
